namespace Aurora {
public sealed class ProcessRow {
    public int Id{get;set;}public string Name{get;set;}public double? Cpu{get;set;}public double? Ram{get;set;}public double? Io{get;set;}public string Path{get;set;}public string Owner{get;set;}public string Assessment{get;set;}public long Started;public bool Candidate;
    internal long CpuTicks,SampleTime;internal ulong IoBytes;internal int Session;internal bool Critical,IoAvailable;
}
public static class ProcessInspector {
    [StructLayout(LayoutKind.Sequential)]struct IoCounters{public ulong ReadOperations,WriteOperations,OtherOperations,ReadBytes,WriteBytes,OtherBytes;}
    [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetProcessIoCounters(IntPtr process,out IoCounters counters);
    [DllImport("kernel32.dll",SetLastError=true)]static extern bool IsProcessCritical(IntPtr process,out bool critical);
    [DllImport("ntdll.dll")]static extern int NtQueryInformationProcess(IntPtr process,int information,out int value,int length,out int returnedLength);
    [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
    [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);
    [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
    static readonly HashSet<string> criticalNames=new HashSet<string>(new[]{"system","idle","registry","secure system","smss","csrss","wininit","winlogon","lsass","services","svchost","dwm","fontdrvhost","audiodg","memory compression","msmpeng","nissrv","securityhealthservice"},StringComparer.OrdinalIgnoreCase);
    public static bool Eligible(string name,string path,string owner,string currentUser,int session,int currentSession,int pid,bool critical){
        if(pid<=4||pid==Process.GetCurrentProcess().Id||critical||criticalNames.Contains(name??"")||session==0||session!=currentSession||owner!=currentUser||String.IsNullOrWhiteSpace(owner)||String.IsNullOrWhiteSpace(path))return false;
        try{string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows).TrimEnd('\\')+"\\";return !System.IO.Path.GetFullPath(path).StartsWith(windows,StringComparison.OrdinalIgnoreCase)&&!path.StartsWith(@"\\");}catch{return false;}
    }
    static ProcessRow Read(Process p){ProcessRow row=new ProcessRow{Id=p.Id,Name=p.ProcessName,Path="",Owner="",Started=0,Session=-1,Critical=true};try{row.CpuTicks=p.TotalProcessorTime.Ticks;row.SampleTime=Stopwatch.GetTimestamp();row.Ram=p.WorkingSet64/1048576.0;row.Started=p.StartTime.ToUniversalTime().Ticks;row.Session=p.SessionId;try{row.Path=p.MainModule.FileName;}catch{}}catch{}
        IntPtr handle=OpenProcess(0x1000,false,p.Id);if(handle==IntPtr.Zero)handle=OpenProcess(0x400,false,p.Id);
        if(handle!=IntPtr.Zero)try{IoCounters io;if(GetProcessIoCounters(handle,out io)){row.IoBytes=io.ReadBytes+io.WriteBytes;row.IoAvailable=true;}bool known=false,c;try{if(IsProcessCritical(handle,out c)){row.Critical=c;known=true;}}catch(EntryPointNotFoundException){}if(!known){int value,length;if(NtQueryInformationProcess(handle,29,out value,4,out length)==0)row.Critical=value!=0;}IntPtr token;if(OpenProcessToken(handle,8,out token))try{using(WindowsIdentity identity=new WindowsIdentity(token))row.Owner=identity.User.Value;}finally{CloseHandle(token);}}finally{CloseHandle(handle);}
        return row;
    }
    public static List<ProcessRow> Sample(){Dictionary<int,ProcessRow> before=new Dictionary<int,ProcessRow>();foreach(Process p in Process.GetProcesses())using(p)try{before[p.Id]=Read(p);}catch{}Thread.Sleep(1200);string user=WindowsIdentity.GetCurrent().User.Value;int session=Process.GetCurrentProcess().SessionId;List<ProcessRow> result=new List<ProcessRow>();foreach(Process p in Process.GetProcesses())using(p)try{ProcessRow row=Read(p),old;if(before.TryGetValue(row.Id,out old)&&old.Started==row.Started&&row.Started!=0){double seconds=(row.SampleTime-old.SampleTime)/(double)Stopwatch.Frequency;if(seconds>0){row.Cpu=Math.Round(Math.Max(0,Math.Min(100,(row.CpuTicks-old.CpuTicks)/(TimeSpan.TicksPerSecond*seconds*Environment.ProcessorCount)*100)),1);if(row.IoAvailable&&old.IoAvailable&&row.IoBytes>=old.IoBytes)row.Io=Math.Round((row.IoBytes-old.IoBytes)/seconds/1048576.0,2);}}if(row.Ram.HasValue)row.Ram=Math.Round(row.Ram.Value,1);row.Candidate=Eligible(row.Name,row.Path,row.Owner,user,row.Session,session,row.Id,row.Critical);row.Assessment=row.Candidate?L.T("Aplicativo do usuário • revisar","User app • review"):L.T("Protegido ou não verificável","Protected or unverifiable");result.Add(row);}catch{}return result.OrderByDescending(x=>x.Cpu).ThenByDescending(x=>x.Ram).ToList();}
    public static Process Validate(ProcessRow expected){Process p=Process.GetProcessById(expected.Id);try{ProcessRow now=Read(p);if(expected.Started==0||now.Started!=expected.Started||!String.Equals(now.Path,expected.Path,StringComparison.OrdinalIgnoreCase)||!Eligible(now.Name,now.Path,now.Owner,WindowsIdentity.GetCurrent().User.Value,now.Session,Process.GetCurrentProcess().SessionId,now.Id,now.Critical))throw new InvalidOperationException(L.T("O processo mudou ou não pode ser encerrado por este módulo.","The process changed or cannot be terminated by this module."));return p;}catch{p.Dispose();throw;}}
    public static string Explain(ProcessRow row){string detail=L.T("Não é possível garantir segurança apenas pelo nome ou consumo. ","Safety cannot be guaranteed from name or usage alone. ");string n=(row.Name??"").ToLowerInvariant();if(new[]{"chrome","msedge","firefox","brave","opera"}.Any(x=>n.Contains(x)))detail+=L.T("Navegadores usam vários processos. Revise abas, extensões, vídeo e o gerenciador de tarefas interno antes de encerrar.","Browsers use multiple processes. Review tabs, extensions, video and the browser's own task manager before closing.");else detail+=L.T("Confira o caminho, o editor e a finalidade do aplicativo. Atualizações, antivírus e indexação podem consumir recursos temporariamente.","Check path, publisher and app purpose. Updates, antivirus and indexing may temporarily use resources.");if(!row.Candidate)detail+=L.T("\nEncerramento bloqueado: processo do sistema, outro usuário, serviço, crítico ou sem informações suficientes.","\nTermination blocked: system process, another user, service, critical or insufficient information.");return detail;}
}
