    void DisableProcessStartup(ProcessRow row){try{List<string> matches=new List<string>();using(var key=Registry.CurrentUser.OpenSubKey(RunPath))if(key!=null)foreach(string name in key.GetValueNames()){string cmd=Convert.ToString(key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames));if(String.Equals(AppIcons.ExecutablePath(cmd),row.Path,StringComparison.OrdinalIgnoreCase))matches.Add(name);}if(matches.Count==0){ShowNotice(T("Nenhuma entrada Run do usuário corresponde ao executável. Revise a aba Inicialização e as preferências do aplicativo.","No current-user Run entry matches the executable. Review Startup and the app's preferences."));return;}if(!Confirm(T("Desativar estas entradas de inicialização?\n","Disable these startup entries?\n")+String.Join("\n",matches.ToArray())))return;foreach(string name in matches){using(var source=Registry.CurrentUser.OpenSubKey(RunPath,true))using(var dest=Registry.CurrentUser.CreateSubKey(RunPath+"-AuroraDisabled")){if(dest.GetValueNames().Contains(name))throw new IOException("Destination entry already exists");object value=source.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames);RegistryValueKind kind=source.GetValueKind(name);string backup=Path.Combine(journal.Folder,"Startup-"+Guid.NewGuid().ToString("N")+".backup");new System.Xml.Linq.XElement("startup",new System.Xml.Linq.XAttribute("name",name),new System.Xml.Linq.XAttribute("source",RunPath),new System.Xml.Linq.XAttribute("destination",RunPath+"-AuroraDisabled"),new System.Xml.Linq.XAttribute("kind",kind),Convert.ToString(value)).Save(backup);dest.SetValue(name,value,kind);if(!Object.Equals(dest.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames),value))throw new IOException("Verification failed");source.DeleteValue(name);journal.Log("Startup prevention",name+" • "+row.Path);}}ShowNotice(T("Inicialização desativada. Para reverter, use Alternar na aba Inicialização.","Startup disabled. To restore, use Toggle in Startup."));}catch(Exception e){ShowNotice(e.Message);}}
}
public static class ProcessChecks {public static int Run(){try{var rows=ProcessInspector.Sample();if(rows.Count==0)throw new Exception("No processes returned");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"process-results.txt"),"PASS: read-only process sample, "+rows.Count+" rows; CPU/RAM/I-O collected. No process terminated.\n"+DateTime.Now.ToString("s"));return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"process-results.txt"),"FAIL: "+e);return 1;}}}
}
